from pathlib import Path

STUDIO = Path(__file__).resolve().parents[1]
ROOT = STUDIO.parent                      # .../Minecraft Channel
PACK = ROOT / "Editing Pack"
CATALOG = STUDIO / "catalog"
ASSETS_DB = CATALOG / "assets.db"
TAXONOMY = CATALOG / "taxonomy.json"
PROJECTS = STUDIO / "projects"
STYLE = STUDIO / "style.json"


def project_dir(slug: str) -> Path:
    p = PROJECTS / slug
    if not p.exists():
        raise SystemExit(f"project '{slug}' not found in {PROJECTS} (create it with: mcs new {slug} ...)")
    return p


def pack_path(rel: str) -> Path:
    return PACK / rel
def hook_text(edl: dict, segs: list[dict], pj: dict, n: int) -> str:
    """A hook must promise the payoff. First short: the episode title; others: a strong on-screen line
    from inside the window, else a tease matched to how the window ends."""
    title = (pj.get("title") or "").upper()
    if n == 1 and title:
        return title[:34] + ("..." if not title.endswith(("!", "?", "...")) else "")
    ids = {s["id"] for s in segs}
    texts = [t["text"] for t in edl.get("text", []) if t.get("seg") in ids and len(t["text"]) <= 22
             and t.get("style") != "label" and not BORING.search(t["text"])]
    if texts:
        return texts[0]
    end_mode = segs[-1].get("mode") or edl.get("mode", "funny")
    return TEASES.get(end_mode, TEASES["funny"])


def make_short(slug: str, n: int, win: dict, edl: dict, pj: dict) -> str:
    main_segs = [s for s in edl["segments"] if not s["id"].startswith("cold")]
    segs = [dict(s) for s in main_segs[win["from"]: win["to"] + 1]]
    ids = {s["id"] for s in segs}
    keep = lambda e: e.get("seg") in ids or ("src_at" in e and "seg" not in e and "at" not in e)  # noqa: E731


def collect_asset_ids(edl: dict) -> list[tuple[str, float | None]]:
    """(asset_id, approx time) for usage tracking."""
    out = []
    for s in edl["segments"]:
        if s.get("asset"):
            out.append((s["asset"], None))
    for group in (edl.get("overlays", []), edl.get("audio", {}).get("sfx", []), edl.get("audio", {}).get("music", [])):
        for e in group:
            if e.get("asset"):
                out.append((e["asset"], e.get("at", e.get("src_at"))))
    return out
