    "confused": "CONFUSED: one eye squinting, head tilted, scratching its head with a stick, question marks around it",
    "shocked": "SHOCKED: jaw dropped, eyes wide, frozen mid-gasp",
}
THUMB_TEXT = {"death": ["TOO DEEP!", "BIG MISTAKE", "NOT AGAIN"], "drown": ["TOO DEEP!", "NO AIR!", "WATER?!"],
              "lava": ["LAVA?!", "TOO HOT!"], "creeper": ["BEHIND YOU", "BOOM!"], "diamonds": ["DIAMONDS!", "JACKPOT"],
              "panic": ["WHAT?!", "HELP!"], "mobs": ["RUN!", "HELP!"], "dig": ["TOO DEEP!", "WRONG WAY"],
              "craft": ["HOW?!", "NOPE"], "build": ["MY HOUSE!"], "nether": ["NOPE!"], "dragon": ["FINAL BOSS"]}


def _hits(text: str, theme: str) -> int:
    t = " " + re.sub(r"[^a-z' ]", " ", text.lower()) + " "
    return sum(len(re.findall(r"(?<![a-z])" + re.escape(k) + r"(?![a-z])", t)) for k in THEMES[theme]["kw"])


def _theme_of(text: str, prefer: str | None = None) -> str | None:
    scores = {k: _hits(text, k) for k in THEMES}
    scores = {k: v for k, v in scores.items() if v}
    if not scores:
        return None
    best = max(scores.values())
    if prefer in scores and scores[prefer] >= best:
        return prefer
    return max(scores, key=lambda k: (scores[k], -PEAK_ORDER.index(k) if k in PEAK_ORDER else -99))


def title_case(s: str) -> str:
    small = {"a", "an", "the", "to", "of", "in", "on", "at", "for", "and", "or", "but", "by", "vs"}
    ws = s.strip().split()
    return " ".join(w if (w.isupper() and len(w) > 1) else (w.lower() if i and w.lower() in small else w[:1].upper() + w[1:])
                    for i, w in enumerate(ws))


def analyze(slug: str) -> dict:
    """Everything the writers need, from project.json / transcript / edit.json."""
    p = PROJECTS / slug
    pj = _read(p / "project.json", {}) or {}
    edl = _read(p / "edit.json", {}) or {}
    words = _transcript_words(slug)
    full = " ".join(w["word"].strip() for w in words)
    spans, total = _spans(edl) if edl.get("segments") else ([], 0.0)
    duration = video_duration(slug) or total
    ctx = pj.get("context", "") or ""
    base = title_case(pj.get("title") or edl.get("title") or slug.replace("-", " "))

    # per-segment theme from the words spoken inside it (cutaways inherit the previous theme)
    seg_info = []
    prev = None
    for s, a, b in spans:
        txt = _text_between(words, s["in"], s["out"]) if s.get("type", "source") == "source" else ""
        th = _theme_of(txt, prev) or prev
        if s.get("id", "").startswith("cold"):
            th = "cold"
        seg_info.append({"id": s.get("id"), "start": a, "end": b, "text": txt, "theme": th, "mode": s.get("mode")})
        if th and th != "cold":
            prev = th

    # episode-level theme presence (context counts triple: it's the creator's own summary)
    present = {k: _hits(full, k) + 3 * _hits(ctx + " " + base, k) for k in THEMES}
    present = {k: v for k, v in present.items() if v}
    tail = " ".join(x["text"] for x in seg_info[int(len(seg_info) * 0.7):]) if seg_info else full[-400:]
    peak_scores = {k: 3 * _hits(ctx, k) + 2 * _hits(tail, k) + _hits(full, k) for k in THEMES if "peak" in THEMES[k]}
    peak_scores = {k: v for k, v in peak_scores.items() if v}
    sad_end = any(x.get("mode") == "sad" for x in seg_info[-4:])
    if peak_scores:
        peak = max(peak_scores, key=lambda k: (peak_scores[k], -PEAK_ORDER.index(k)))
        if "death" in peak_scores and sad_end:
            peak = "death" if peak_scores.get("drown", 0) < peak_scores["death"] else "drown"
    else:
        peak = next((k for k in PEAK_ORDER if k in present), None)

    used = []
    for aid, _ in _collect_ids(edl):
        a = _lookup(aid)
        if a:
            used.append(a)
    return {"slug": slug, "pj": pj, "edl": edl, "words": words, "full": full, "ctx": ctx, "base": base,
            "duration": duration, "segs": seg_info, "present": present, "peak": peak, "sad_end": sad_end,
            "assets": used,
            "text_pops": [t.get("text") for t in edl.get("text", []) if t.get("text")],
            "titles_on_screen": [o.get("vars", {}).get("title") or o.get("vars", {}).get("text")
                                 for o in edl.get("overlays", []) if o.get("type") == "motion"
                                 and (o.get("vars", {}).get("title") or o.get("vars", {}).get("text"))]}


def _collect_ids(edl: dict):
    try:
        from .edl import collect_asset_ids
        return collect_asset_ids(edl)
    except Exception:  # noqa: BLE001
        return []


# ------------------------------------------------------------------ chapters
def chapters(info: dict) -> list[dict]:
    """[{t, label}] in OUTPUT time. YouTube rules: first at 0:00, >= 3 chapters, each >= 10 s, video >= 60 s."""
    if info["duration"] < 60 or not info["segs"]:
        return []
    runs: list[dict] = []
    for s in info["segs"]:
        th = s["theme"] if s["theme"] != "cold" else None
        if runs and (th is None or runs[-1]["theme"] == th):
            runs[-1]["end"] = s["end"]
            continue
        runs.append({"theme": th, "start": s["start"], "end": s["end"]})
    runs[0]["start"] = 0.0
    # cold opens / unthemed starts belong to the intro
    if runs[0]["theme"] is None and len(runs) > 1:
        runs[1]["start"] = 0.0
        runs.pop(0)
    # merge anything shorter than 10 s into its neighbour (the first chapter absorbs forward)
    changed = True
    while changed and len(runs) > 1:
        changed = False
        for i, r in enumerate(runs):
            if r["end"] - r["start"] < 10:
                if i == 0:
                    runs[1]["start"] = 0.0
                    runs[1]["theme"] = runs[1]["theme"] if runs[0]["theme"] is None else runs[0]["theme"]
                    runs.pop(0)
                else:
                    runs[i - 1]["end"] = r["end"]
                    runs.pop(i)
                changed = True
                break
    # equal neighbours after merging
    merged = []
    for r in runs:
        if merged and merged[-1]["theme"] == r["theme"]:
            merged[-1]["end"] = r["end"]
        else:
            merged.append(r)
    runs = merged
    out = []
    for i, r in enumerate(runs):
        th = r["theme"]
        if i == 0:
            label = "The Challenge" if "challenge" in (info["full"] + info["ctx"]).lower() else "Intro"
        elif i == len(runs) - 1 and info.get("peak") in ("death", "drown", "lava", "creeper", "mobs", "panic") \
                and th in ("death", "drown", "panic", "lava", "creeper", "mobs", info["peak"]):
            label = "It Goes Horribly Wrong"
        else:
            label = THEMES[th]["chapter"] if th in THEMES else f"Part {i + 1}"
        out.append({"t": round(r["start"], 2), "label": label, "theme": th})
    seen = set()
    for c in out:                      # no duplicate labels
        while c["label"] in seen:
            c["label"] += " (cont.)"
        seen.add(c["label"])
    return out if len(out) >= 3 else []


def ts(t: float) -> str:
    t = int(t)
    return f"{t // 3600}:{t % 3600 // 60:02d}:{t % 60:02d}" if t >= 3600 else f"{t // 60}:{t % 60:02d}"


# ------------------------------------------------------------------ credits
def credits(info: dict) -> tuple[list[str], list[str]]:
    lines, warns, seen = [], [], set()
    for a in info["assets"]:
        if a["id"] in seen:
            continue
        seen.add(a["id"])
        notes = a.get("notes") or ""
        title = a.get("title") or a["id"]
        m = re.search(r"credit:\s*([^;(]+)(\(([^)]*)\))?", notes, re.I)
        is_audio = a.get("kind") == "audio" or (a.get("category") or "").lower() in ("music", "sound effects")
        if m:
            who, lic = m.group(1).strip(), (m.group(3) or "").strip()
            track = re.sub(r"\s*[-(]?\s*kevin mac ?leod.*$", "", title, flags=re.I)
            track = re.sub(r"\s*-\s*(gaming )?background music.*$", "", track, flags=re.I).strip(" -")
            if "macleod" in who.lower():
                lines.append(f'"{track}" Kevin MacLeod (incompetech.com)\n'
                             "Licensed under Creative Commons: By Attribution 4.0 License\n"
                             "http://creativecommons.org/licenses/by/4.0/")
            else:
                lines.append(f'"{track}" by {who}' + (f" ({lic})" if lic else ""))
        elif is_audio and (a.get("category") == "music" or a["id"].startswith("music")) and \
                re.search(r"unknown|unidentified", notes + " " + title, re.I):
            warns.append(f"Music \"{title}\" has an unknown licence: possible Content ID claim. "
                         "Swap it for a credited track before uploading, or check the claim in YouTube Studio.")
        elif (a.get("copyright_risk") or "") == "high":
            warns.append(f"\"{title}\" is marked high copyright risk.")
    cf = PROJECTS / info["slug"] / "CREDITS.txt"
    if cf.exists():
        lines += [ln for ln in cf.read_text(encoding="utf-8").strip().split("\n\n") if ln.strip()]
    return lines, warns


# ------------------------------------------------------------------ heuristic writer
def _fit(s: str, n: int) -> bool:
    return 0 < len(s) <= n


def heuristic(info: dict) -> dict:
    base, present, peak = info["base"], info["present"], info["peak"]
    bad_end = peak in ("death", "drown", "lava", "creeper", "mobs", "panic")
    order = sorted(present, key=lambda k: -present[k])
    titles = []
    if bad_end:
        titles += [f"{base}… It Went Horribly Wrong", f"{base} (and Instantly Regretted It)"]
    elif peak == "diamonds":
        titles += [f"{base}… and Found DIAMONDS", f"{base} (Best Decision Ever)"]
    else:
        titles += [f"{base}… Here's What Happened", f"{base} (It Didn't Go to Plan)"]
    if "dig" in present:
        titles.append("Digging Straight Down in Minecraft Was a Mistake" if bad_end
                      else "Digging Straight Down in Minecraft")
    if "craft" in present:
        titles.append("I Can't Even Craft a Pickaxe… (Dig to Bedrock)" if "dig" in present
                      else "Crafting in Minecraft Shouldn't Be This Hard")
    if "challenge" in (info["full"] + info["ctx"]).lower():
        titles.append(f"The {re.sub(r'^I (Tried )?(To )?', '', base, flags=re.I).strip()} Challenge Went Wrong"
                      if bad_end else f"The {base} Challenge")
    titles.append(f"{base}" + (" (Minecraft Gone Wrong)" if bad_end else " | Minecraft"))
    titles = [re.sub(r"\s+", " ", t).strip() for t in titles]
    titles = list(dict.fromkeys(t for t in titles if _fit(t, 60)))[:5]

    # hook + summary grounded in the detected story order
    story = []
    for s in info["segs"]:
        th = s["theme"]
        if th in THEMES and th not in story:
            story.append(th)
    task = base[0].lower() + base[1:] if base[:2] != "I " else base
    hook = (f"{task} in Minecraft… and it did NOT go to plan." if bad_end
            else f"{task} in Minecraft. Here's how it went.")
    hook = hook[0].upper() + hook[1:]
    sents = []
    if "challenge" in (info["full"] + info["ctx"]).lower() and "dig" in present:
        sents.append("The challenge: dig straight down, all the way to bedrock.")
    for th in story:
        if th in ("death", "drown", "panic") and bad_end:
            continue
        if th == "dig" and sents and "dig straight down" in sents[0]:
            sents.append("Then it was finally time to start digging. What could possibly go wrong?")
            continue
        sents.append(THEMES[th]["summary"])
    if bad_end:
        sents.append("Let's just say the bottom came faster than expected." if "dig" in present and peak in ("drown", "death")
                     else THEMES[peak]["summary"])
    summary = " ".join(sents[:4])

    tags = ["minecraft", "minecraft funny", "minecraft funny moments", "minecraft challenge", "minecraft gameplay",
            "minecraft survival"]
    for th in order:
        tags += THEMES[th]["tags"]
    tags += ["minecraft fails" if bad_end else "minecraft lets play", "funny minecraft video", "minecraft memes",
             "crodie", "crodie minecraft", "minecraft 1.21"]
    hashtags = ["#minecraft", "#minecraftfunny", (THEMES[peak]["hashtag"] if peak else "#minecraftchallenge")]
    if "challenge" in (info["full"] + info["ctx"]).lower():
        hashtags[2] = "#minecraftchallenge"

    th_texts = THUMB_TEXT.get(peak or "", []) + [x for k in order for x in THUMB_TEXT.get(k, [])]
    th_texts = list(dict.fromkeys(th_texts))[:4] or ["NO WAY!"]
    expression = EXPRESSIONS.get(THEMES.get(peak, {}).get("peak", "shocked"), EXPRESSIONS["shocked"])
    scene_bits = [THEMES[k]["scene"] for k in ["dig", "nether", "dragon", "build", "craft"] if k in present
                  and "scene" in THEMES[k]][:1]
    if peak and "scene" in THEMES[peak]:
        scene_bits.append(THEMES[peak]["scene"])
    if not scene_bits:
        scene_bits = ["a dramatic Minecraft landscape at golden hour"]
    prop = "gripping a stone pickaxe" if "craft" in present or "dig" in present else ""
    return {"title_options": titles, "hook": hook, "summary": summary, "tags": tags, "hashtags": hashtags,
            "thumbnail_text_options": th_texts, "thumbnail_text": th_texts[0], "expression": expression,
            "scene": "; ".join(scene_bits), "prop": prop, "chapter_labels": None}


def heuristic_short(info: dict, short_slug: str, parent_h: dict) -> dict:
    p = PROJECTS / short_slug
    edl = _read(p / "edit.json", {}) or {}
    pj = _read(p / "project.json", {}) or {}
    txt = " ".join(_text_between(info["words"], s["in"], s["out"]) for s in edl.get("segments", [])
                   if s.get("type", "source") == "source")
    pops = " ".join(t.get("text", "") for t in edl.get("text", []))
    scores = {k: _hits(txt + " " + pops, k) for k in THEMES}
    sad = any(s.get("mode") == "sad" for s in edl.get("segments", []))
    th = max(scores, key=lambda k: (scores[k], k in ("death", "panic") and sad)) if any(scores.values()) else None
    if sad and (scores.get("death") or scores.get("panic")):
        th = "death"
    first = edl.get("segments", [{}])[0].get("id") == "s001"
    if first and "challenge" in txt.lower():
        title = "Can I Dig All the Way to Bedrock?" if "dig" in info["present"] else f"{info['base']}?"
        desc = f"Day one of the challenge: {info['base'].lower()}. Full video on the channel!"
        th = "dig" if "dig" in info["present"] else th
    elif th:
        title = THEMES[th]["short"]
        desc = {"craft": "Crafting a pickaxe should take five seconds. It did not.",
                "death": "Digging straight down… what could go wrong? Full video on the channel!",
                "drown": "One block too far. Full video on the channel!",
                "dig": "Rule #1 of Minecraft: never dig straight down.",
                }.get(th, f"From \"{info['base']}\". Full video on the channel!")
    else:
        title = (pj.get("title") or info["base"]).title()[:40]
        desc = f"From \"{info['base']}\". Full video on the channel!"
    title = title[:40].rstrip()
    tags = ["minecraft", "minecraft shorts", "shorts", "minecraft funny"] + (THEMES[th]["tags"][:3] if th else []) + \
           ["crodie"]
    exp_key = THEMES.get(th, {}).get("peak") or ("confused" if th == "craft" else "shocked")
    text = (THUMB_TEXT.get(th) or ["WAIT…"])[0]
    if th == "craft":
        text = "HOW?!"
    scene = THEMES.get(th, {}).get("scene") or parent_h["scene"]
    return {"slug": short_slug, "title": title, "description": desc, "tags": list(dict.fromkeys(tags)),
            "thumbnail_text": text, "expression": EXPRESSIONS[exp_key], "scene": scene, "theme": th}


# ------------------------------------------------------------------ claude CLI writer
def claude_bin() -> str | None:
    if os.environ.get("MCS_PUBLISH_LLM", "1") == "0":
        return None
    return shutil.which("claude")


def llm(info: dict, chaps: list[dict], short_infos: list[dict]) -> dict | None:
    cb = claude_bin()
    if not cb:
        return None
    lines = []
    for s in info["segs"]:
        if s["text"]:
            lines.append(f"[{ts(s['start'])}] {s['text']}")
    shorts_desc = "\n".join(f"- {s['slug']}: on-screen hook \"{s.get('hook', '')}\"; speech: {s.get('speech', '')[:300]}"
                            for s in short_infos) or "(none)"
    b = brand()
    prompt = f"""You write YouTube metadata for the Minecraft channel {b.get('channel_name', 'CRODIE')} ("{b.get('tagline', '')}").
Mascot: Crodie, a cute blocky lime-green Minecraft-style lizard.
Episode working title: {info['base']}
Creator's notes: {info['ctx']}
Final video length: {ts(info['duration'])}
On-screen text pops: {', '.join(info['text_pops'][:15])}
Transcript of the FINAL edit, in output time (auto-transcribed, may be messy):
{chr(10).join(lines)[:6000]}

Chapter start times already chosen (output time): {', '.join(ts(c['t']) for c in chaps) or 'none'}

Shorts cut from this episode:
{shorts_desc}

Rules: be grounded in what actually happens (no clickbait lies). Minecraft-YouTube voice, punchy, curious.
Return ONLY a JSON object, no prose, with keys:
 "title_options": 5 titles, best first, each <= 60 chars (e.g. "I Tried to Dig to Bedrock… It Went Horribly Wrong"),
 "hook": one-line first sentence of the description,
 "summary": 2-3 sentences summarising the episode,
 "chapter_labels": one short label per chapter time above (same count),
 "tags": 15-25 YouTube tags (broad + specific + "crodie"),
 "hashtags": exactly 3, first "#minecraft",
 "thumbnail_text_options": 3 options of 2-4 HUGE words (e.g. "TOO DEEP!"),
 "expression": Crodie's exaggerated facial expression and pose for the thumbnail, matching the peak moment,
 "scene": the Minecraft scene behind Crodie, one sentence, relating to the video,
 "shorts": [{{"slug", "title" (<= 40 chars, no hashtag), "description" (1-2 lines), "tags" (6-10),
             "thumbnail_text", "expression", "scene"}}] one per short above.
"""
    try:
        r = subprocess.run([cb, "-p", "--output-format", "json"], input=prompt, capture_output=True, text=True,
                           encoding="utf-8", errors="replace", timeout=LLM_TIMEOUT, cwd=str(ROOT))
    except (OSError, subprocess.TimeoutExpired) as e:
        print(f"claude CLI failed ({e}); using the built-in writer")
        return None
    if r.returncode != 0:
        print(f"claude CLI exit {r.returncode}: {r.stderr[-300:]}; using the built-in writer")
        return None
    text = r.stdout
    try:
        env = json.loads(text)
        text = env.get("result", text) if isinstance(env, dict) else text
    except ValueError:
        pass
    m = re.search(r"\{.*\}", text or "", re.S)
    if not m:
        print("claude CLI returned no JSON; using the built-in writer")
        return None
    try:
        return json.loads(m.group(0))
    except ValueError:
        print("claude CLI returned invalid JSON; using the built-in writer")
        return None


