def thumb_prompt(title: str, expression: str, scene: str, text: str | None, prop: str = "",
                 vertical: bool = False) -> str:
    fmt = ("a 9:16 vertical YouTube Shorts cover (1080x1920)" if vertical
           else "a 16:9 YouTube thumbnail (1280x720)")
    place = ("Crodie large in the middle third, filling most of the width" if vertical
             else "Crodie large and dead-centre, about 60% of the frame height, the clear hero of the image")
    if text:
        where = ("in the top third" if vertical else "across the top of the frame, above/beside Crodie's head")
        text_block = (f'TEXT: render the exact words "{text}" in huge chunky blocky Minecraft-style letters, white fill '
                      f"with a thick orange (#EF7718) outline and a dark drop shadow, slightly tilted, {where}. "
