"""YouTube publishing data per episode:  projects/<slug>/publish.json

    python -m mcstudio.publish generate <slug> [--no-llm]     (prints "@@RESULT {json}" for the UI job)
    python -m mcstudio.publish show <slug>

Pipeline statuses, in order:
    editing   -> no final render yet
    rendered  -> out/<slug>.mp4 exists: "Awaiting upload"
    uploaded  -> uploaded to YouTube as private/unlisted, not live yet
    scheduled -> has a future scheduled_at (YouTube will publish it)
    published -> live (youtube_url)
    archived  -> hidden from the board

Shorts are projects named <slug>--short-N; their copy lives in the parent's publish.json under "shorts".

generate() writes title options, description (with output-time chapters + music credits), tags, hashtags and
ready-to-paste ChatGPT image prompts centred on the Crodie mascot. It asks the local `claude` CLI for the
creative bits when it is on PATH and falls back to a keyword/heuristic writer otherwise. Structure
(chapters, credits, length limits, the mascot description) is always assembled here, so output stays valid.
"""
from __future__ import annotations

import json
import os
import re
import shutil
import subprocess
import sys
from datetime import datetime
from pathlib import Path

from .paths import PROJECTS, ROOT, STUDIO

STATUSES = ["editing", "rendered", "uploaded", "scheduled", "published", "archived"]
STATUS_LABELS = {"editing": "Editing", "rendered": "Awaiting upload", "uploaded": "Uploaded",
                 "scheduled": "Scheduled", "published": "Published", "archived": "Archived"}
USER_FIELDS = {"status", "scheduled_at", "uploaded_at", "youtube_url", "notes"}   # never overwritten by generate
TEXT_FIELDS = {"title", "title_options", "description", "tags", "hashtags", "thumbnail_prompt",
               "thumbnail_prompt_no_text", "shorts_cover_prompt", "thumbnail_text", "thumbnail_text_options"}
TAG_CHAR_LIMIT = 480        # YouTube allows 500; leave headroom for its own quoting
LLM_TIMEOUT = 90


# ------------------------------------------------------------------ io helpers
def _read(p: Path, default=None):
    try:
        return json.loads(p.read_text(encoding="utf-8"))
    except (OSError, ValueError):
        return default


def _write(p: Path, data) -> None:
    p.write_text(json.dumps(data, indent=2, ensure_ascii=False), encoding="utf-8")


def brand() -> dict:
    return _read(STUDIO / "brand" / "brand.json", {}) or {}


def channel_handle() -> str:
    b = brand()
    h = (b.get("watermark") or {}).get("text") or ""
    return h if h.startswith("@") else "@" + (b.get("channel_name") or "Crodie").title()


def final_video(slug: str) -> Path | None:
    f = PROJECTS / slug / "out" / f"{slug}.mp4"
    return f if f.exists() else None


def thumbnail_file(slug: str) -> Path | None:
    for ext in ("png", "jpg", "jpeg", "webp"):
        f = PROJECTS / slug / f"thumbnail.{ext}"
        if f.exists():
            return f
    return None


def is_short(slug: str) -> bool:
    return "--short-" in slug


def parent_of(slug: str) -> str:
    return slug.split("--short-")[0]


def shorts_of(slug: str) -> list[str]:
    kids = [c.name for c in PROJECTS.glob(f"{slug}--short-*") if (c / "project.json").exists()]
    return sorted(kids, key=lambda s: int(re.sub(r"\D", "", s.rsplit("-", 1)[-1]) or 0))


def _parse_dt(s: str | None) -> datetime | None:
    if not s:
        return None
    try:
        d = datetime.fromisoformat(str(s).replace("Z", "+00:00"))
        return d.astimezone().replace(tzinfo=None) if d.tzinfo else d   # compare as local naive time
    except ValueError:
        return None


def default_status(slug: str) -> str:
    pj = _read(PROJECTS / slug / "project.json", {}) or {}
    if pj.get("kind") == "demo" or slug.startswith("_"):
        return "archived"
    return "rendered" if final_video(slug) else "editing"


def effective_status(slug: str, data: dict | None) -> str:
    """Stored status, auto-advanced where the facts say so (render finished, schedule time passed)."""
    st = (data or {}).get("status") or default_status(slug)
    if st == "editing" and final_video(slug):
        st = "rendered"
    if st == "scheduled":
        d = _parse_dt((data or {}).get("scheduled_at"))
        if d and d <= datetime.now():
            st = "published"
    return st


def load(slug: str) -> dict:
    """publish.json (or an empty skeleton) with the effective status filled in."""
    data = _read(PROJECTS / slug / "publish.json", {}) or {}
    out = {"status": None, "title": "", "title_options": [], "description": "", "tags": [], "hashtags": [],
           "thumbnail_text": "", "thumbnail_text_options": [], "thumbnail_prompt": "", "thumbnail_prompt_no_text": "",
           "shorts_cover_prompt": "", "scheduled_at": "", "uploaded_at": "", "youtube_url": "", "notes": "",
           "shorts": [], "warnings": [], "generated_at": None, "generator": None, **data}
    out["stored_status"] = data.get("status")
    out["status"] = effective_status(slug, data)
    # make sure every existing short has an entry, with its own effective status
    have = {s.get("slug"): s for s in out["shorts"] if isinstance(s, dict)}
    shorts = []
    for k in shorts_of(slug):
        s = dict(have.get(k) or {"slug": k, "title": "", "description": "", "tags": [], "cover_prompt": ""})
        s["status"] = effective_status(k, s)
        f = final_video(k)
        s["video"] = f"out/{f.name}" if f else None
        shorts.append(s)
    out["shorts"] = shorts
    return out


def save(slug: str, data: dict) -> dict:
    keep = {k: v for k, v in data.items() if k not in ("stored_status",)}
    for s in keep.get("shorts") or []:
        s.pop("video", None)
    _write(PROJECTS / slug / "publish.json", keep)
    return load(slug)


def patch(slug: str, fields: dict) -> dict:
    """Apply a partial update with status rules. Raises ValueError on invalid input."""
    if is_short(slug):
        return patch_short(parent_of(slug), slug, fields)
    cur = load(slug)
    fields = dict(fields)
    if "tags" in fields and isinstance(fields["tags"], str):
        fields["tags"] = split_tags(fields["tags"])
    if "hashtags" in fields and isinstance(fields["hashtags"], str):
        fields["hashtags"] = [h if h.startswith("#") else "#" + h for h in fields["hashtags"].replace(",", " ").split()]
    shorts_patch = fields.pop("shorts", None)
    status = fields.pop("status", None)
    if status is not None and status not in STATUSES:
        raise ValueError(f"status must be one of {STATUSES}")
    allowed = USER_FIELDS | TEXT_FIELDS | {"warnings"}
    bad = set(fields) - allowed
    if bad:
        raise ValueError(f"unknown fields: {sorted(bad)}")
    new = {**cur, **fields}
    now = datetime.now()
    sched = _parse_dt(new.get("scheduled_at"))
    if new.get("scheduled_at") and not sched:
        raise ValueError("scheduled_at must be an ISO date/time, e.g. 2026-10-12T17:00")
    if status is None:
        if "scheduled_at" in fields and sched:
            status = "scheduled" if sched > now else ("published" if new.get("youtube_url") else "uploaded")
        elif fields.get("youtube_url") and cur["status"] in ("editing", "rendered"):
            status = "published" if (sched and sched <= now) or not sched else "uploaded"
            if sched and sched > now:
                status = "scheduled"
        elif "scheduled_at" in fields and not fields["scheduled_at"] and cur["status"] == "scheduled":
            status = "uploaded"
    if status == "scheduled":
        if not sched:
            raise ValueError("set a schedule date/time before moving to Scheduled")
    if status:
        new["status"] = status
    elif cur.get("stored_status"):
        new["status"] = cur["stored_status"]
    else:
        new["status"] = cur["status"]
    if new["status"] in ("uploaded", "scheduled", "published") and not new.get("uploaded_at"):
        new["uploaded_at"] = now.isoformat(timespec="minutes")
    if shorts_patch:
        by = {s["slug"]: s for s in new["shorts"]}
        for sp in shorts_patch:
            if sp.get("slug") in by:
                _apply_short(by[sp["slug"]], sp)
    return save(slug, new)


def _apply_short(s: dict, sp: dict) -> None:
    sp = dict(sp)
    if isinstance(sp.get("tags"), str):
        sp["tags"] = split_tags(sp["tags"])
    st = sp.get("status")
    if st is not None and st not in STATUSES:
        raise ValueError(f"status must be one of {STATUSES}")
    sched = _parse_dt(sp.get("scheduled_at"))
    if st is None and sp.get("scheduled_at") and sched:
        sp["status"] = "scheduled" if sched > datetime.now() else "published"
    if sp.get("status") == "scheduled" and not (sched or _parse_dt(s.get("scheduled_at"))):
        raise ValueError("set a schedule date/time before moving a short to Scheduled")
    s.update({k: v for k, v in sp.items() if k != "slug"})


def patch_short(parent: str, slug: str, fields: dict) -> dict:
    return patch(parent, {"shorts": [{**fields, "slug": slug}]})


def split_tags(s: str) -> list[str]:
    return [t.strip() for t in re.split(r"[,\n]", s) if t.strip()]


def tags_chars(tags: list[str]) -> int:
    """Characters YouTube counts: tags joined by commas, multi-word tags wrapped in quotes."""
    return sum(len(t) + (2 if " " in t else 0) for t in tags) + max(0, len(tags) - 1)


# ------------------------------------------------------------------ content extraction
def _transcript_words(slug: str) -> list[dict]:
    t = _read(PROJECTS / slug / "work" / "transcript.json", {}) or {}
    words = []
    for seg in t.get("segments", []):
        if seg.get("words"):
            words += [w for w in seg["words"] if "start" in w]
        else:
            words.append({"word": seg.get("text", ""), "start": seg.get("start", 0), "end": seg.get("end", 0)})
    return words


def _text_between(words: list[dict], a: float, b: float) -> str:
    return " ".join(w["word"].strip() for w in words if a - 0.05 <= w["start"] < b)


def _lookup(aid):
    from . import assets as A
    try:
        return A.get(aid)
    except Exception:  # noqa: BLE001 - missing DB / unknown id must not break publishing
        return None


def _spans(edl: dict):
    from .edl import build_spans, seg_duration
    out, t = [], 0.0
    for s in edl.get("segments", []):
        try:
            d = seg_duration(s, _lookup)
        except Exception:  # noqa: BLE001
            d = 0.0
        out.append((s, t, t + d))
        t += d
    return out, t


def video_duration(slug: str) -> float:
    p = PROJECTS / slug
    rep = _read(p / "work" / "full" / "render_report.json")
    if rep and rep.get("duration_s"):
        return float(rep["duration_s"])
    edl = _read(p / "edit.json")
    if edl:
        return _spans(edl)[1]
    return float((_read(p / "project.json", {}) or {}).get("duration_s") or 0)


