PEAK_ORDER = ["death", "drown", "lava", "creeper", "mobs", "diamonds", "panic", "dragon", "nether", "dig", "craft",
              "build"]
EXPRESSIONS = {
    "terrified": "TERRIFIED: eyes huge and wide with tiny pupils, mouth stretched wide open in a scream, both "
