        "against the background, shallow depth of field (background softly blurred), punchy colour grade, bold clean "
        "silhouette, no clutter, no extra characters, no watermark, no UI." + safe,
        text_block,
    ])


# ------------------------------------------------------------------ assemble
def _clean_tags(tags: list[str], must: list[str]) -> list[str]:
    out, seen = [], set()
    for t in list(must) + list(tags):
        t = re.sub(r"[<>\"#,]", "", str(t)).strip().lower()
        if t and t not in seen and len(t) <= 30:
            seen.add(t)
            out.append(t)
    while len(out) > 25 or tags_chars(out) > TAG_CHAR_LIMIT:
        out.pop()
    return out


def _hashtags(hs: list[str]) -> list[str]:
    out = ["#minecraft"]
    for h in hs or []:
        h = "#" + re.sub(r"[^a-z0-9]", "", str(h).lower())
        if len(h) > 1 and h not in out:
            out.append(h)
    return (out + ["#minecraftfunny", "#crodie"])[:3] if len(out) < 3 else out[:3]


def generate(slug: str, use_llm: bool = True) -> dict:
    if is_short(slug):
        slug = parent_of(slug)
    p = PROJECTS / slug
    if not (p / "project.json").exists():
        raise SystemExit(f"no project {slug}")
    info = analyze(slug)
    chaps = chapters(info)
    h = heuristic(info)
    kids = shorts_of(slug)
    short_infos = []
    for k in kids:
        e = _read(PROJECTS / k / "edit.json", {}) or {}
        speech = " ".join(_text_between(info["words"], s["in"], s["out"]) for s in e.get("segments", [])
                          if s.get("type", "source") == "source")
        hook = next((o.get("vars", {}).get("text") for o in e.get("overlays", []) if o.get("template") == "hook"
                     or o.get("vars", {}).get("text")), "") or (_read(PROJECTS / k / "project.json", {}) or {}).get("title", "")
        short_infos.append({"slug": k, "hook": hook, "speech": speech})

    gen = "heuristic"
    L = llm(info, chaps, short_infos) if use_llm else None
    if L:
        gen = "claude"
    L = L or {}

    def pick(key, valid):
        v = L.get(key)
        return v if v is not None and valid(v) else h[key]

    titles = [t.strip() for t in (L.get("title_options") or []) if isinstance(t, str) and _fit(t.strip(), 60)]
    titles = list(dict.fromkeys(titles + h["title_options"]))[:5]
    hook = pick("hook", lambda v: isinstance(v, str) and 10 < len(v) < 160)
    summary = pick("summary", lambda v: isinstance(v, str) and 20 < len(v) < 700)
    labels = L.get("chapter_labels")
    if isinstance(labels, list) and len(labels) == len(chaps):
        for c, lab in zip(chaps, labels):
            if isinstance(lab, str) and 1 < len(lab) <= 50:
                c["label"] = lab.strip()
    tags = _clean_tags(pick("tags", lambda v: isinstance(v, list) and len(v) >= 8) + h["tags"],
                       ["minecraft", "crodie"])
    hashtags = _hashtags(pick("hashtags", lambda v: isinstance(v, list) and v))
    tto = [t.strip().upper() for t in (L.get("thumbnail_text_options") or []) if isinstance(t, str)
           and 0 < len(t.split()) <= 4] + h["thumbnail_text_options"]
    tto = list(dict.fromkeys(tto))[:4]
    expression = pick("expression", lambda v: isinstance(v, str) and len(v) > 10)
    scene = pick("scene", lambda v: isinstance(v, str) and len(v) > 10)
    cred, warns = credits(info)

    handle = channel_handle()
    b = brand()
    parts = [hook, summary]
    if chaps:
        parts.append("⏱ Chapters\n" + "\n".join(f"{ts(c['t'])} {c['label']}" for c in chaps))
    parts.append(f"🦎 New here? Subscribe to {handle} for more {b.get('tagline') or 'Minecraft'}! "
                 "Drop a comment with what I should try next 👇")
    if cred:
        parts.append("🎵 Music & credits\n" + "\n\n".join(cred))
    parts.append(" ".join(hashtags))
    description = "\n\n".join(x for x in parts if x)

    title = titles[0]
    data = load(slug)
    data.update({
        "title": title, "title_options": titles, "description": description, "tags": tags, "hashtags": hashtags,
        "thumbnail_text": tto[0], "thumbnail_text_options": tto,
        "thumbnail_prompt": thumb_prompt(title, expression, scene, tto[0], h["prop"]),
        "thumbnail_prompt_no_text": thumb_prompt(title, expression, scene, None, h["prop"]),
        "shorts_cover_prompt": thumb_prompt(title, expression, scene, tto[0], h["prop"], vertical=True),
        "chapters": [{"t": c["t"], "ts": ts(c["t"]), "label": c["label"]} for c in chaps],
        "duration_s": round(info["duration"], 2),
        "warnings": warns + ([] if chaps or info["duration"] < 60 else
                             ["Not enough distinct parts for YouTube chapters (needs 3+ chapters of 10s+)."]),
        "generated_at": datetime.now().isoformat(timespec="seconds"), "generator": gen,
    })
    llm_shorts = {s.get("slug"): s for s in (L.get("shorts") or []) if isinstance(s, dict)}
    new_shorts = []
    for s in data["shorts"]:
        hs = heuristic_short(info, s["slug"], h)
        ls = llm_shorts.get(s["slug"], {})
        st = (ls.get("title") if isinstance(ls.get("title"), str) and _fit(ls["title"].strip(), 40) else hs["title"]).strip()
        st = re.sub(r"\s*#shorts\s*$", "", st, flags=re.I)
        desc = ls.get("description") if isinstance(ls.get("description"), str) and ls["description"].strip() else hs["description"]
        stags = _clean_tags((ls.get("tags") if isinstance(ls.get("tags"), list) else []) + hs["tags"],
                            ["minecraft", "shorts", "crodie"])[:12]
        text = (ls.get("thumbnail_text") or hs["thumbnail_text"]).upper()
        exp = ls.get("expression") if isinstance(ls.get("expression"), str) and len(ls["expression"]) > 10 else hs["expression"]
        sc = ls.get("scene") if isinstance(ls.get("scene"), str) and len(ls["scene"]) > 10 else hs["scene"]
        s.update({"title": f"{st} #shorts", "description": f"{desc}\n\nFull video: \"{title}\" on {handle}\n#shorts #minecraft",
                  "tags": stags, "thumbnail_text": text,
                  "cover_prompt": thumb_prompt(st, exp, sc, text, h["prop"] if hs["theme"] in ("dig", "craft") else "",
                                               vertical=True)})
        new_shorts.append(s)
    data["shorts"] = new_shorts
    if (p / "publish.json").exists():
        hist = p / "history"
        hist.mkdir(exist_ok=True)
        shutil.copy2(p / "publish.json", hist / f"publish.{datetime.now():%Y%m%d-%H%M%S}.json")
    if not data.get("stored_status"):
        data["status"] = default_status(slug)
    else:
        data["status"] = data["stored_status"]
    return save(slug, data)


# ------------------------------------------------------------------ poster frame for the board
def poster(slug: str) -> str | None:
    """Relative path (inside the project) of a small poster image: thumbnail.* > cached frame of the final."""
    t = thumbnail_file(slug)
    if t:
        return t.name
    f = final_video(slug) or next(iter(sorted((PROJECTS / slug / "out").glob("*_preview.mp4"))), None) \
        if (PROJECTS / slug / "out").exists() else None
    if not f:
        sheets = sorted((PROJECTS / slug / "work" / "sheets").glob("*.jpg")) if (PROJECTS / slug / "work" / "sheets").exists() else []
        return f"work/sheets/{sheets[0].name}" if sheets else None
    out = PROJECTS / slug / "work" / "publish_poster.jpg"
    if out.exists() and out.stat().st_mtime >= f.stat().st_mtime:
        return "work/publish_poster.jpg"
    out.parent.mkdir(exist_ok=True)
    dur = video_duration(slug) or 10
    try:
        subprocess.run(["ffmpeg", "-y", "-loglevel", "error", "-ss", f"{min(dur * 0.4, 30):.2f}", "-i", str(f),
                        "-frames:v", "1", "-vf", "scale=480:-2", str(out)], capture_output=True, timeout=20)
    except (OSError, subprocess.TimeoutExpired):
        return None
    return "work/publish_poster.jpg" if out.exists() else None


def pipeline() -> list[dict]:
    rows = []
    for p in sorted(PROJECTS.iterdir()):
        if not (p / "project.json").exists() or is_short(p.name):
            continue
        pj = _read(p / "project.json", {}) or {}
        if pj.get("kind") == "short":
            continue
        d = load(p.name)
        f = final_video(p.name)
        rows.append({
            "slug": p.name, "title": d.get("title") or pj.get("title") or p.name, "working_title": pj.get("title"),
            "status": d["status"], "kind": pj.get("kind", "episode"), "scheduled_at": d.get("scheduled_at"),
            "uploaded_at": d.get("uploaded_at"), "youtube_url": d.get("youtube_url"),
            "duration_s": d.get("duration_s") or (video_duration(p.name) if f else None),
            "video": f"out/{f.name}" if f else None, "poster": poster(p.name),
            "generated": bool(d.get("generated_at")), "has_thumbnail": bool(thumbnail_file(p.name)),
            "shorts": [{"slug": s["slug"], "title": s.get("title"), "status": s["status"]} for s in d["shorts"]],
            "modified": datetime.fromtimestamp(max((x.stat().st_mtime for x in p.glob("*.json")),
                                                   default=p.stat().st_mtime)).isoformat(timespec="seconds"),
        })
    return rows


def checklist(slug: str, d: dict) -> dict:
    return {"video": bool(final_video(slug)), "title": bool(d.get("title")), "description": bool(d.get("description")),
            "tags": bool(d.get("tags")), "thumbnail": bool(thumbnail_file(slug)),
            "thumbnail_prompt": bool(d.get("thumbnail_prompt")),
            "scheduled": d["status"] in ("scheduled", "published") or bool(d.get("scheduled_at"))}


def main(argv=None) -> int:
    import argparse
    ap = argparse.ArgumentParser(prog="python -m mcstudio.publish")
    sub = ap.add_subparsers(dest="cmd", required=True)
    g = sub.add_parser("generate")
    g.add_argument("slug")
    g.add_argument("--no-llm", action="store_true")
    s = sub.add_parser("show")
    s.add_argument("slug")
    a = ap.parse_args(argv)
    if a.cmd == "generate":
        print(f"Writing publishing metadata for {a.slug}" + ("" if a.no_llm or not claude_bin() else " (asking claude…)"))
        d = generate(a.slug, use_llm=not a.no_llm)
        print(f"generator: {d['generator']}  title: {d['title']}")
        print(f"{len(d['tags'])} tags ({tags_chars(d['tags'])} chars), {len(d.get('chapters', []))} chapters, "
              f"{len(d['shorts'])} shorts")
        for w in d.get("warnings", []):
            print("WARN", w)
        print("@@RESULT " + json.dumps({"slug": parent_of(a.slug), "title": d["title"], "generator": d["generator"]}))
    else:
        print(json.dumps(load(a.slug), indent=2, ensure_ascii=False))
    return 0


if __name__ == "__main__":
    sys.stdout.reconfigure(encoding="utf-8")
    raise SystemExit(main())

