input.content:
// ---------------------------------------------------------------- publishing (YouTube pipeline)
const PUB_COLS = ["editing", "rendered", "uploaded", "scheduled", "published"];
const PUB_LABELS = { editing: "Editing", rendered: "Awaiting upload", uploaded: "Uploaded", scheduled: "Scheduled", published: "Published", archived: "Archived" };
const PUB_HINT = { editing: "still being cut", rendered: "final render ready", uploaded: "private / unlisted on YouTube", scheduled: "goes live automatically", published: "live" };
const mmss = (t) => t == null || isNaN(t) ? "–" : `${Math.floor(t / 60)}:${String(Math.floor(t % 60)).padStart(2, "0")}`;
const fmtWhen = (s) => { if (!s) return ""; const d = new Date(s); return isNaN(d) ? s : d.toLocaleString([], { weekday: "short", month: "short", day: "numeric", hour: "numeric", minute: "2-digit" }); };
const tagChars = (tags) => tags.reduce((n, t) => n + t.length + (t.includes(" ") ? 2 : 0), 0) + Math.max(0, tags.length - 1);
const splitTags = (s) => s.split(/[,\n]/).map((t) => t.trim()).filter(Boolean);
const pubUrl = (slug) => `/api/projects/${encodeURIComponent(slug)}/publish`;

async function copyText(text, label = "Copied") {
  try { await navigator.clipboard.writeText(text); toast(`${label} ✓`); return; } catch {}
  const ta = document.createElement("textarea");   // fallback: old-school select + execCommand
  ta.value = text; ta.style.cssText = "position:fixed;opacity:0;left:-9999px"; document.body.appendChild(ta); ta.select();
  let ok = false; try { ok = document.execCommand("copy"); } catch {}
  ta.remove();
  toast(ok ? `${label} ✓` : "Couldn't copy automatically: select the text and press Ctrl+C", !ok);
}

function openPublish(slug) { store.set("tab:" + slug, "publish"); location.hash = "#/project/" + encodeURIComponent(slug); }

async function movePublish(slug, status) {
  try {
    await api(pubUrl(slug), { method: "PATCH", body: { status } });
    toast(`Moved to ${PUB_LABELS[status]}`);
    return true;
  } catch (e) {
    if (status === "scheduled") { toast("Pick a schedule date/time first", true); openPublish(slug); }
    else toast(e.message, true);
    return false;
  }
}

async function Pipeline() {
  let d;
  try { d = await api("/api/pipeline"); } catch (e) { view.innerHTML = `<div class="empty">${esc(e.message)}</div>`; return; }
  const showArch = store.get("pubArchived", false);
  const cols = showArch ? [...PUB_COLS, "archived"] : PUB_COLS;
  const byCol = Object.fromEntries(cols.map((c) => [c, []]));
  for (const it of d.items) if (byCol[it.status]) byCol[it.status].push(it);
  const nArch = d.items.filter((i) => i.status === "archived").length;
  view.innerHTML = `<div class="row"><div><h1>Publishing</h1><p class="sub">Every episode from edit to live. Drag cards between columns or use ← →. Click a card for its title, description, tags and thumbnail prompt.</p></div>
      <span class="spacer"></span><label class="row check"><input type="checkbox" id="pubArch" ${showArch ? "checked" : ""}> show archived (${nArch})</label></div>
    <div class="kanban" style="grid-template-columns:repeat(${cols.length}, minmax(210px, 1fr))">${cols.map((c) => `
      <div class="kcol" data-col="${c}"><div class="khead"><b>${PUB_LABELS[c]}</b><span class="badge">${byCol[c].length}</span></div>
        <div class="faint" style="font-size:11px;margin:-4px 0 8px">${PUB_HINT[c] || "hidden from the board"}</div>
        <div class="kcards">${byCol[c].map((it) => pubCard(it, cols)).join("") || `<div class="kempty">drop here</div>`}</div></div>`).join("")}</div>`;
  $("#pubArch").onchange = (e) => { store.set("pubArchived", e.target.checked); Pipeline(); };
  $$(".kcard").forEach((c) => {
    c.onclick = (e) => { if (!e.target.closest("button, a")) openPublish(c.dataset.slug); };
    c.ondragstart = (e) => { e.dataTransfer.setData("text/plain", c.dataset.slug); e.dataTransfer.effectAllowed = "move"; c.classList.add("dragging"); };
    c.ondragend = () => c.classList.remove("dragging");
  });
  $$(".kcard [data-move]").forEach((b) => (b.onclick = async (e) => {
    e.stopPropagation();
    if (await movePublish(b.closest(".kcard").dataset.slug, b.dataset.move)) Pipeline();
  }));
  $$(".kcol").forEach((col) => {
    col.ondragover = (e) => { e.preventDefault(); col.classList.add("over"); };
    col.ondragleave = (e) => { if (!col.contains(e.relatedTarget)) col.classList.remove("over"); };
    col.ondrop = async (e) => {
      e.preventDefault(); col.classList.remove("over");
      const slug = e.dataTransfer.getData("text/plain");
      const it = d.items.find((i) => i.slug === slug);
      if (it && it.status !== col.dataset.col && await movePublish(slug, col.dataset.col)) Pipeline();
    };
  });
  pollers.push(setInterval(() => { if (location.hash === "#/pipeline" && !document.querySelector(".kcard.dragging")) refreshPipelineQuietly(); }, 30000));
}
async function refreshPipelineQuietly() { try { await api("/api/pipeline"); Pipeline(); } catch {} }   // scheduled -> published flips on its own

function pubCard(it, cols) {
  const i = cols.indexOf(it.status);
  const prev = cols[i - 1], next = cols[i + 1];
  const poster = it.poster ? `/media/project/${encodeURIComponent(it.slug)}/${enc(it.poster)}?v=${encodeURIComponent(it.modified)}` : null;
  const shortsUp = it.shorts.filter((s) => ["uploaded", "scheduled", "published"].includes(s.status)).length;
  return `<div class="kcard" draggable="true" data-slug="${esc(it.slug)}">
    <div class="kposter" ${poster ? `style="background-image:url('${poster}')"` : ""}>${poster ? "" : `<span class="faint">no render yet</span>`}
      ${it.duration_s ? `<span class="dur">${mmss(it.duration_s)}</span>` : ""}${it.has_thumbnail ? `<span class="kthumb" title="thumbnail added">🖼</span>` : ""}</div>
    <div class="ktitle">${esc(it.title)}</div>
    <div class="faint mono" style="font-size:11px">${esc(it.slug)}${it.kind === "demo" ? " · demo" : ""}</div>
    <div class="row" style="gap:5px">
      ${it.shorts.length ? `<span class="badge" title="${esc(it.shorts.map((s) => `${s.slug}: ${PUB_LABELS[s.status]}`).join("\n"))}">▮ ${it.shorts.length} shorts${shortsUp ? ` · ${shortsUp} up` : ""}</span>` : ""}
      ${it.generated ? `<span class="badge r-clean">copy ready</span>` : it.video ? `<span class="badge r-mild">needs copy</span>` : ""}</div>
    ${it.scheduled_at && ["scheduled", "published", "uploaded"].includes(it.status) ? `<div class="kwhen">🗓 ${esc(fmtWhen(it.scheduled_at))}</div>` : ""}
    ${it.youtube_url ? `<a class="kwhen" href="${esc(it.youtube_url)}" target="_blank" rel="noopener">▶ watch on YouTube</a>` : ""}
    <div class="row kmove"><button class="btn small" ${prev ? `data-move="${prev}" title="Move to ${PUB_LABELS[prev]}"` : "disabled"}>←</button><span class="spacer"></span>
      <button class="btn small" ${next ? `data-move="${next}" title="Move to ${PUB_LABELS[next]}"` : "disabled"}>→</button></div></div>`;
}

const PUB_FIELDS = [
  ["title", "Title", 2, "YouTube max 100 · aim for ≤ 60 so it isn't cut off"],
  ["description", "Description", 14, "hook · summary · chapters · subscribe · credits · hashtags"],
  ["tags", "Tags", 4, "comma separated · YouTube limit 500 characters"],
  ["hashtags", "Hashtags", 1, "the first three show above the title"],
  ["thumbnail_text", "Thumbnail text", 1, "2–4 huge words (changing it updates the prompts)"],
  ["thumbnail_prompt", "Thumbnail prompt · with text (ChatGPT)", 10, "paste into ChatGPT with the reference images attached"],
  ["thumbnail_prompt_no_text", "Thumbnail prompt · no text", 8, "leaves space to add the text yourself"],
  ["shorts_cover_prompt", "Shorts cover prompt · 9:16", 8, "vertical cover for the shorts"],
];
const pubVal = (d, k) => k === "tags" ? (d.tags || []).join(", ") : k === "hashtags" ? (d.hashtags || []).join(" ") : (d[k] ?? "");

function pubCounter(k, v) {
  if (k === "title") return `<span class="${v.length > 100 ? "err" : v.length > 60 ? "warn" : "faint"}">${v.length}/60</span>`;
  if (k === "description") return `<span class="${v.length > 5000 ? "err" : "faint"}">${v.length}/5000</span>`;
  if (k === "tags") { const t = splitTags(v), n = tagChars(t); return `<span class="${n > 500 ? "err" : n > 450 ? "warn" : "faint"}">${t.length} tags · ${n}/500</span>`; }
  return "";
}

function pubCopyAll(d) {
  return [["TITLE", d.title], ["DESCRIPTION", d.description], ["TAGS", (d.tags || []).join(", ")], ["HASHTAGS", (d.hashtags || []).join(" ")],
    ["THUMBNAIL TEXT", d.thumbnail_text], ["THUMBNAIL PROMPT (ChatGPT)", d.thumbnail_prompt], ["THUMBNAIL PROMPT (no text)", d.thumbnail_prompt_no_text],
    ["SHORTS COVER PROMPT (9:16)", d.shorts_cover_prompt],
    ...(d.shorts || []).map((s, i) => [`SHORT ${i + 1} (${s.slug})`, `${s.title}\n\n${s.description}\n\nTags: ${(s.tags || []).join(", ")}`])]
    .filter(([, v]) => v).map(([h, v]) => `=== ${h} ===\n${v}`).join("\n\n");
}

async function PublishTab(p, el) {
  const slug = p.kind === "short" && p.parent ? p.parent : p.slug;
  let d;
  try { d = await api(pubUrl(slug)); } catch (e) { el.innerHTML = `<div class="empty">${esc(e.message)}</div>`; return; }
  const timers = {};
  const flashSaved = () => { const s = $("#pubSaved"); if (s) { s.textContent = "saved ✓"; clearTimeout(flashSaved._t); flashSaved._t = setTimeout(() => (s.textContent = ""), 1500); } };
  const save = (url, field, value, after) => {   // debounced autosave per field
    clearTimeout(timers[url + field]);
    timers[url + field] = setTimeout(async () => {
      try { const nd = await api(url, { method: "PATCH", body: { [field]: value } }); after?.(nd); flashSaved(); }
      catch (e) { toast(e.message, true); }
    }, 650);
  };
  const checklist = (c) => [["video", "final video"], ["title", "title"], ["description", "description"], ["tags", "tags"], ["thumbnail", "thumbnail image"], ["scheduled", "scheduled"]]
    .map(([k, l]) => `<span class="ck ${c[k] ? "on" : ""}">${c[k] ? "✓" : "○"} ${l}</span>`).join("");

  function pubShort(s) {
    const vid = s.video ? `/media/project/${encodeURIComponent(s.slug)}/${enc(s.video)}` : null;
    const f = (k, label, rows) => `<div class="pub-field"><div class="row"><b>${label}</b>${k === "tags" ? `<span class="faint" data-scount="${esc(s.slug)}">${tagChars(s.tags || [])}/500</span>` : k === "title" ? `<span class="faint" data-stcount="${esc(s.slug)}">${(s.title || "").length}/100</span>` : ""}<span class="spacer"></span><button class="btn small" data-scopy="${k}" data-slug="${esc(s.slug)}">⧉ Copy</button></div>
      <textarea data-sk="${k}" data-slug="${esc(s.slug)}" rows="${rows}" spellcheck="${k === "cover_prompt" ? "false" : "true"}">${esc(k === "tags" ? (s.tags || []).join(", ") : s[k] || "")}</textarea></div>`;
    return `<div class="card pub-short ${p.slug === s.slug ? "hl" : ""}" data-short="${esc(s.slug)}">
      <div class="pub-short-vid">${vid ? `<video class="vert" controls preload="metadata" src="${vid}"></video>` : `<div class="empty vert">not rendered</div>`}
        <a class="btn small" href="#/project/${encodeURIComponent(s.slug)}" style="margin-top:6px">Open ${esc(s.slug)}</a></div>
      <div class="pub-short-body">
        <div class="row">
          <label class="field">Status<select data-sstatus="${esc(s.slug)}">${d.statuses.map((x) => `<option value="${x}" ${x === s.status ? "selected" : ""}>${esc(d.status_labels[x])}</option>`).join("")}</select></label>
          <label class="field">Scheduled for<input type="datetime-local" data-swhen="${esc(s.slug)}" value="${esc((s.scheduled_at || "").slice(0, 16))}"></label>
          <span class="spacer"></span><button class="btn small" data-sall="${esc(s.slug)}">⧉ Copy all</button>
        </div>
        ${f("title", "Title", 1)}${f("description", "Description", 4)}${f("tags", "Tags", 2)}${f("cover_prompt", "Cover prompt · 9:16", 4)}
      </div></div>`;
  }

  function render() {
    const vidUrl = d.video ? `/media/project/${encodeURIComponent(slug)}/${enc(d.video)}` : null;
    const thumbUrl = d.thumbnail ? `/media/project/${encodeURIComponent(slug)}/${enc(d.thumbnail)}?v=${d.thumbnail_mtime}` : null;
    el.innerHTML = `
      ${p.slug !== slug ? `<div class="card warn" style="margin-bottom:12px">This short's copy lives with its episode <a href="#/project/${encodeURIComponent(slug)}">${esc(slug)}</a>: it's highlighted under <b>Shorts</b> below.</div>` : ""}
      <div class="card pub-top">
        <div class="row">
          <label class="field">Status<select id="pubStatus">${d.statuses.map((s) => `<option value="${s}" ${s === d.status ? "selected" : ""}>${esc(d.status_labels[s])}</option>`).join("")}</select></label>
          <label class="field">Scheduled for (your local time)<input type="datetime-local" id="pubWhen" value="${esc((d.scheduled_at || "").slice(0, 16))}"></label>
          <label class="field" style="flex:1;min-width:240px">YouTube URL<input type="text" id="pubUrl" placeholder="https://youtu.be/…" value="${esc(d.youtube_url || "")}"></label>
        </div>
        <div class="row" style="margin-top:12px">
          <button class="btn primary" id="pubGen">✨ ${d.generated_at ? "Regenerate" : "Generate"} title, description, tags &amp; prompts</button>
          <button class="btn" id="pubAll">⧉ Copy all</button>
          <span class="faint" style="font-size:12px">${d.generated_at ? `written ${esc(d.generated_at.replace("T", " "))} by ${d.generator === "claude" ? "Claude" : "the built-in writer"}` : "nothing generated yet"}${d.claude ? "" : " · claude CLI not found, using the built-in writer"}</span>
          <span class="spacer"></span><span id="pubSaved" class="faint" style="font-size:12px"></span>
        </div>
        <div id="pubJob" class="faint mono" style="font-size:12px;margin-top:6px;white-space:pre-wrap"></div>
        <div class="checklist" id="pubCheck">${checklist(d.checklist)}</div>
        ${(d.warnings || []).map((w) => `<div class="warn">⚠ ${esc(w)}</div>`).join("")}
      </div>
      <div class="pub-grid">
        <div class="pub-main">
          ${d.title_options?.length ? `<div class="pub-field"><div class="row"><b>Title options</b><span class="faint" style="font-size:12px">click one to use it</span></div>
            <div class="chips" style="margin-top:6px">${d.title_options.map((t) => `<span class="chip ${t === d.title ? "on" : ""}" data-title="${esc(t)}">${esc(t)} <span class="faint">${t.length}</span></span>`).join("")}</div></div>` : ""}
          ${PUB_FIELDS.map(([k, label, rows, hint]) => { const v = pubVal(d, k); return `<div class="pub-field">
            <div class="row"><b>${label}</b><span data-count="${k}">${pubCounter(k, v)}</span><span class="spacer"></span><button class="btn small" data-copy="${k}">⧉ Copy</button></div>
            ${k === "thumbnail_text" && d.thumbnail_text_options?.length ? `<div class="chips" style="margin:4px 0">${d.thumbnail_text_options.map((t) => `<span class="chip ${t === d.thumbnail_text ? "on" : ""}" data-ttext="${esc(t)}">${esc(t)}</span>`).join("")}</div>` : ""}
            <textarea data-k="${k}" rows="${rows}" spellcheck="${k.includes("prompt") ? "false" : "true"}">${esc(v)}</textarea>
            <div class="faint" style="font-size:11px">${hint}</div></div>`; }).join("")}
        </div>
        <div class="pub-side">
          <div class="card"><b>Final video</b>
            ${vidUrl ? `<video class="main" style="margin-top:8px" controls preload="metadata" src="${vidUrl}"></video>
              <div class="mono faint" style="font-size:11px;word-break:break-all;margin:6px 0">${esc(d.video_path)}</div>
              <div class="row"><button class="btn small" id="pubFolder">📂 Open folder</button><a class="btn small" href="${vidUrl}" download>⬇ Download</a><button class="btn small" id="pubPath">⧉ Copy path</button></div>`
              : `<div class="empty" style="padding:20px;margin-top:8px">No final render yet (out/${esc(slug)}.mp4). Render the final from the Pipeline tab.</div>`}
          </div>
          <div class="card" style="margin-top:12px"><b>Thumbnail</b>
            ${thumbUrl ? `<img class="pub-thumb" src="${thumbUrl}" alt="thumbnail">` : `<p class="muted" style="font-size:13px">1. Copy a thumbnail prompt. 2. In ChatGPT, attach <span class="mono">Crodie/profile pic.png</span> and <span class="mono">Crodie/mc skin.png</span>, paste the prompt, generate. 3. Add the image here so it's saved with the episode.</p>`}
            <label class="btn small" style="display:inline-block;margin-top:8px">⬆ ${thumbUrl ? "Replace" : "Add"} thumbnail image<input type="file" id="pubThumb" accept="image/png,image/jpeg,image/webp" hidden></label>
          </div>
          ${d.chapters?.length ? `<div class="card" style="margin-top:12px"><b>Chapters</b><div class="mono" style="margin-top:6px">${d.chapters.map((c) => `<div>${esc(c.ts)} ${esc(c.label)}</div>`).join("")}</div></div>` : ""}
          <div class="card" style="margin-top:12px"><b>Notes</b><textarea data-k="notes" rows="4" placeholder="anything to remember for this upload">${esc(d.notes || "")}</textarea></div>
        </div>
      </div>
      <h2>Shorts (${d.shorts.length})</h2>
      ${d.shorts.length ? `<div class="pub-shorts">${d.shorts.map(pubShort).join("")}</div>` : `<div class="empty">No shorts for this episode yet. Cut them from the Shorts tab.</div>`}`;
    wire();
  }

  function wire() {
    const url = pubUrl(slug);
    const refreshMeta = (nd) => { d = nd; const c = $("#pubCheck"); if (c) c.innerHTML = checklist(d.checklist); };
    const patchNow = async (body, msg) => {
      try { d = await api(url, { method: "PATCH", body }); if (msg) toast(msg(d)); render(); }
      catch (err) { toast(err.message, true); render(); }
    };
    $("#pubStatus").onchange = (e) => patchNow({ status: e.target.value }, (nd) => `Status: ${nd.status_labels[nd.status]}`);
    $("#pubWhen").onchange = (e) => patchNow({ scheduled_at: e.target.value }, (nd) => e.target.value ? `Scheduled for ${fmtWhen(e.target.value)} · ${nd.status_labels[nd.status]}` : "Schedule cleared");
    $("#pubUrl").onchange = (e) => patchNow({ youtube_url: e.target.value.trim() }, (nd) => `Saved · ${nd.status_labels[nd.status]}`);
    $$("textarea[data-k]", el).forEach((ta) => (ta.oninput = () => {
      const k = ta.dataset.k;
      const c = $(`[data-count="${k}"]`, el); if (c) c.innerHTML = pubCounter(k, ta.value);
      save(url, k, ta.value, (nd) => {
        refreshMeta(nd);
        if (k === "thumbnail_text") ["thumbnail_prompt", "shorts_cover_prompt"].forEach((pk) => { const t = $(`textarea[data-k="${pk}"]`, el); if (t && document.activeElement !== t) t.value = nd[pk] || ""; });
      });
    }));
    $$("[data-copy]", el).forEach((b) => (b.onclick = () => {
      const k = b.dataset.copy, ta = $(`textarea[data-k="${k}"]`, el);
      const v = ta ? ta.value : pubVal(d, k);
      if (!v.trim()) return toast("Nothing to copy yet: hit ✨ Generate", true);
      copyText(v, `${PUB_FIELDS.find((f) => f[0] === k)?.[1] || k} copied`);
    }));
    $("#pubAll").onclick = () => d.title ? copyText(pubCopyAll(d), "Everything copied") : toast("Nothing to copy yet: hit ✨ Generate", true);
    $$("[data-title]", el).forEach((c) => (c.onclick = () => patchNow({ title: c.dataset.title }, () => "Title set")));
    $$("[data-ttext]", el).forEach((c) => (c.onclick = () => patchNow({ thumbnail_text: c.dataset.ttext }, () => "Thumbnail text set (prompts updated)")));
    $("#pubGen").onclick = async () => {
      if (d.generated_at && !confirm("Regenerate? This replaces the title, description, tags and prompts (status, schedule and URL are kept). The current version is backed up in history/.")) return;
      try { const j = await api(url + "/generate", { method: "POST" }); watchJob(j.id); } catch (e) { toast(e.message, true); }
    };
    if (d.job) watchJob(d.job.id);
    $("#pubFolder")?.addEventListener("click", () => api(url + "/open-folder", { method: "POST" }).catch((e) => toast(e.message, true)));
    $("#pubPath")?.addEventListener("click", () => copyText(d.video_path, "Path copied"));
    $("#pubThumb").onchange = async (e) => {
      const file = e.target.files[0]; if (!file) return;
      const fd = new FormData(); fd.append("file", file);
      try {
        const r = await fetch(url + "/thumbnail", { method: "POST", body: fd });
        if (!r.ok) throw new Error((await r.json().catch(() => ({}))).detail || r.statusText);
        d = await r.json(); render(); toast("Thumbnail saved");
      } catch (err) { toast(err.message, true); }
    };
    // shorts: each one autosaves into the episode's publish.json via its own slug
    $$("textarea[data-sk]", el).forEach((ta) => (ta.oninput = () => {
      const k = ta.dataset.sk, s = ta.dataset.slug;
      if (k === "tags") $(`[data-scount="${s}"]`, el).textContent = `${tagChars(splitTags(ta.value))}/500`;
      if (k === "title") $(`[data-stcount="${s}"]`, el).textContent = `${ta.value.length}/100`;
      save(pubUrl(s), k, ta.value, refreshMeta);
    }));
    $$("[data-scopy]", el).forEach((b) => (b.onclick = () => {
      const ta = $(`textarea[data-sk="${b.dataset.scopy}"][data-slug="${b.dataset.slug}"]`, el);
      ta.value.trim() ? copyText(ta.value, "Copied") : toast("Nothing to copy yet", true);
    }));
    $$("[data-sall]", el).forEach((b) => (b.onclick = () => {
      const s = d.shorts.find((x) => x.slug === b.dataset.sall);
      copyText(`${s.title}\n\n${s.description}\n\nTags: ${(s.tags || []).join(", ")}`, "Short copied");
    }));
    $$("[data-sstatus]", el).forEach((sel) => (sel.onchange = async () => {
      try { d = await api(pubUrl(sel.dataset.sstatus), { method: "PATCH", body: { status: sel.value } }); toast(`Short: ${d.status_labels[sel.value]}`); }
      catch (e) { toast(e.message, true); sel.value = d.shorts.find((x) => x.slug === sel.dataset.sstatus)?.status; }
    }));
    $$("[data-swhen]", el).forEach((inp) => (inp.onchange = async () => {
      try { d = await api(pubUrl(inp.dataset.swhen), { method: "PATCH", body: { scheduled_at: inp.value } }); render(); toast(inp.value ? `Short scheduled for ${fmtWhen(inp.value)}` : "Schedule cleared"); }
      catch (e) { toast(e.message, true); }
    }));
    if (p.slug !== slug) $(`[data-short="${p.slug}"]`, el)?.scrollIntoView({ block: "center" });
  }

  function watchJob(id) {
    const gen = $("#pubGen"), box = $("#pubJob");
    gen.disabled = true; gen.textContent = "✨ Writing…";
    const iv = setInterval(async () => {
      let j; try { j = await api(`/api/jobs/${id}?tail=6`); } catch { return; }
      if (box) box.textContent = j.log.slice(-2).join("  ·  ");
      if (j.status === "running") return;
      clearInterval(iv);
      if (j.status === "done") { d = await api(pubUrl(slug)); render(); toast("Metadata written ✨"); }
      else { toast("Generation failed: see the log", true); gen.disabled = false; gen.textContent = "✨ Generate"; if (box) box.textContent = j.log.slice(-6).join("\n"); }
    }, 1000);
    pollers.push(iv);
  }

  render();
}

