.kempty { border: 1px dashed var(--line); border-radius: 6px; padding: 18px; text-align: center; color: var(--faint); font-size: 12px; }
.kcard { background: var(--panel); border: 1px solid var(--line); border-radius: var(--radius); padding: 8px; display: grid; gap: 6px; cursor: pointer; transition: border-color .12s, transform .12s; }
.kcard:hover { border-color: #4a5158; transform: translateY(-1px); }
.kcard.dragging { opacity: .45; }
.kposter { aspect-ratio: 16/9; border-radius: 5px; background: #0b0c0d center/cover no-repeat; position: relative; display: grid; place-items: center; font-size: 12px; }
.kposter .dur { position: absolute; right: 5px; bottom: 5px; background: rgba(0,0,0,.75); padding: 1px 6px; border-radius: 4px; font-size: 11px; font-variant-numeric: tabular-nums; }
.kthumb { position: absolute; left: 5px; top: 5px; background: rgba(0,0,0,.6); border-radius: 4px; padding: 0 4px; font-size: 12px; }
.ktitle { font-weight: 600; font-size: 13px; line-height: 1.3; }
.kwhen { font-size: 12px; color: var(--diamond); text-decoration: none; }
.kmove .btn { padding: 1px 10px; }
.pub-top .field { min-width: 180px; }
input[type=datetime-local] { background: #0f1012; border: 1px solid var(--line); border-radius: 6px; padding: 6px 10px; color: var(--text); color-scheme: dark; }
.checklist { display: flex; gap: 8px; flex-wrap: wrap; margin: 10px 0 4px; }
.ck { font-size: 12px; padding: 2px 9px; border-radius: 99px; border: 1px solid var(--line); color: var(--faint); }
.ck.on { color: #d8f5cc; border-color: var(--grass-d); background: rgba(95,191,58,.12); }
.pub-grid { display: grid; grid-template-columns: minmax(0, 1.5fr) minmax(280px, 1fr); gap: 16px; margin-top: 16px; align-items: start; }
