.pub-field textarea[data-k=title], .pub-field textarea[data-sk=title] { font-family: inherit; font-size: 15px; font-weight: 600; }
.pub-thumb { width: 100%; border-radius: 6px; margin-top: 8px; border: 1px solid var(--line); }
.pub-shorts { display: grid; gap: 14px; }
